import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 转换请求中的父批次消费项。
 *
 * @param lotId           父批次编号
 * @param expectedVersion 调用方预期的父批次版本号
 * @param quantity        本次消费量，三位小数，必须为正
 */
public record ParentInput(
        @NotBlank String lotId,
        @NotNull Long expectedVersion,
        @NotNull @DecimalMin(value = "0.000", inclusive = false)
        @Digits(integer = 16, fraction = 3) BigDecimal quantity
) {
}

package com.example.starter.lot.api;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 转换请求中的子批次产出项。
 *
 * @param lotId    新子批次编号，必须不存在（与现有批次冲突则整笔回滚）
 * @param quantity 本次产出量，三位小数，必须为正
 */
public record ChildOutput(
        @NotBlank String lotId,
        @NotNull @DecimalMin(value = "0.000", inclusive = false)
        @Digits(integer = 16, fraction = 3) BigDecimal quantity
) {
}

package com.example.starter.lot.api;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.util.List;

/**
 * 转换请求：原子消费多个父批次并产生多个新子批次。
 *
 * @param requestId    业务幂等键；同键同完整参数返回首次结果，同键异参返回 409
 * @param parents      父批次消费列表（含 expectedVersion）
 * @param children     子批次产出列表（新批次 ID）
 * @param allowedLoss  本次允许损耗上限 = 总消费 - 总产出 的最大差额，非负三位小数
 * @param unit         本次转换统一计量单位
 */
public record TransformRequest(
        @NotBlank String requestId,
        @NotEmpty @Valid List<ParentInput> parents,
        @NotEmpty @Valid List<ChildOutput> children,
        @NotNull @DecimalMin(value = "0.000", inclusive = true)
        @Digits(integer = 16, fraction = 3) BigDecimal allowedLoss,
        @NotBlank String unit
) {
}

package com.example.starter.lot.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 隔离设置/解除请求。
 *
 * @param action SET 设置隔离 / RELEASE 解除该批次自身来源
 * @param reason 原因（合成数据，可空）
 */
public record QuarantineRequest(
        @NotBlank String lotId,
        @NotBlank String action,
        String reason
) {
}

package com.example.starter.lot.api;

import com.example.starter.lot.model.LotStatus;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 批次视图：主信息 + 当前生效隔离来源。
 */
public record LotView(
        String lotId,
        String unit,
        BigDecimal initialQty,
        BigDecimal availableQty,
        BigDecimal consumedQty,
        LotStatus status,
        long version,
        List<String> activeQuarantineSources,
        LocalDateTime createdAt
) {
}

