                .andExpect(status().isNotFound());
    }

    @Test
    @DisplayName("转换主流程：合并两父批次产出子批次，余额与谱系可查询")
    void transformEndpointHappyPath() throws Exception {
        String a = uid("A");
        String b = uid("B");
